//! 🧰️ Actual source owner laws debit every turn from the existing neutral finite stock.
use crate::{RetainedCloneSourceAdmission,RetainedCloneSource,RetainedCloneGrant as G,RetainedCloneProgress as P,RetainedWorkOutcome,RetirementDemand,ValueError};
use crate::retirement::RetireOwned;
pub struct Bank{remaining:G,cpu:u64}
impl Bank{
 pub fn new()->Self{let f:serde_json::Value=serde_json::from_str(include_str!("../🎟️work/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();Self{remaining:serde_json::from_value(f["stock"].clone()).unwrap(),cpu:f["maximumCpuWork"].as_u64().unwrap()}}
 pub fn from_stock(remaining:G,cpu:u64)->Self{Self{remaining,cpu}}
 pub fn grant(&self,d:RetirementDemand)->G{let g=G{maximum_items:usize::from(self.remaining.maximum_items>0&&self.cpu>0),maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};assert!(g.maximum_copy_bytes<=self.remaining.maximum_copy_bytes&&g.maximum_capacity_bytes<=self.remaining.maximum_capacity_bytes&&g.maximum_release_bytes<=self.remaining.maximum_release_bytes&&g.maximum_depth<=self.remaining.maximum_depth);g}
 pub fn observe<R>(&mut self,g:G,run:impl FnOnce()->RetainedWorkOutcome<R>,receipt:impl FnOnce(&R)->P)->(RetainedWorkOutcome<R>,(usize,usize)){let(turn,heap)=crate::allocation_testing::observe_retirement_allocations(run);assert!(turn.work<=self.cpu);self.cpu-=turn.work;let p=match &turn.result{Ok(value)=>receipt(value),Err(error)=>error.retained_progress()};assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));self.remaining.maximum_items=self.remaining.maximum_items.checked_sub(p.copied_items).unwrap();self.remaining.maximum_copy_bytes=self.remaining.maximum_copy_bytes.checked_sub(p.copied_bytes).unwrap();self.remaining.maximum_capacity_bytes=self.remaining.maximum_capacity_bytes.checked_sub(p.retained_capacity_bytes).unwrap();self.remaining.maximum_release_bytes=self.remaining.maximum_release_bytes.checked_sub(p.released_bytes).unwrap();(turn,heap)}
 pub fn run<R>(&mut self,g:G,run:impl FnOnce()->RetainedWorkOutcome<R>,receipt:impl FnOnce(&R)->P)->(Result<R,ValueError>,(usize,usize)){let(turn,heap)=self.observe(g,run,receipt);(turn.result,heap)}
 pub fn success<R>(&mut self,g:G,run:impl FnOnce()->RetainedWorkOutcome<R>,receipt:impl FnOnce(&R)->P)->(R,(usize,usize)){let(result,heap)=self.run(g,run,receipt);(result.unwrap(),heap)}
 pub fn source<T:Sync+'static,A:RetireOwned+Sync,B:RetireOwned>(&mut self,mut admission:RetainedCloneSourceAdmission<T,A,B>)->(RetainedCloneSource<T,A>,P){let mut total=P::default();let mut output=None;for _ in 0..1048576{if admission.terminal_is_empty(){break}let g=self.grant(admission.next_demand().unwrap());let(result,_)=self.run(g,||if admission.phase()=="ready"{admission.take_output(&mut output,g)}else{admission.advance(g)},|step|step.progress());let p=result.unwrap().progress();total=total.checked_add(p).unwrap();}assert!(admission.terminal_is_empty());(output.unwrap(),total)}
 pub fn denied<T:Sync+'static,A:RetireOwned+Sync,B:RetireOwned>(&mut self,admission:&mut RetainedCloneSourceAdmission<T,A,B>,axis:&str){let d=admission.next_demand().unwrap();let g=self.grant(d);let short=match axis{"items"=>G{maximum_items:0,..g},"capacity"=>G{maximum_capacity_bytes:d.capacity_bytes-1,..g},"depth"=>G{maximum_depth:0,..g},_=>panic!("unknown independent source denial axis")};let(turn,heap)=crate::allocation_testing::observe_retirement_allocations(||admission.advance(short));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),P::default());assert_eq!(heap,(0,0));}
 pub fn return_inputs<T:Sync+'static,A:RetireOwned+Sync,B:RetireOwned>(&mut self,mut admission:RetainedCloneSourceAdmission<T,A,B>)->(A,B){let mut output=None;for _ in 0..1048576{if admission.terminal_is_empty(){break}let g=self.grant(admission.next_return_demand().unwrap());let(result,_)=self.run(g,||admission.return_inputs(&mut output,g),|step|step.progress());result.unwrap();}assert!(admission.terminal_is_empty());output.unwrap()}
}
